import { buildUniqueSuffix, futureIsoDate } from './helpers.js';

export function buildInitiatePayload(keyword) {
  const unique = buildUniqueSuffix();
  const keywordValue = Number.isFinite(keyword) ? keyword : parseInt(keyword, 10);
  const ownerDocumentId = '12345678';

  return {
    referencia: `REF-${keywordValue}-${unique}`,
    keyword: keywordValue,
    titulo: `Contrato ${unique}`,
    horaExpiracion: futureIsoDate(1),
    idTiposNotificacion: ['email'],
    documentos: [
      {
        name: `contrato-${unique}.pdf`,
        ownerClientId: [ownerDocumentId],
        s3KeyOriginal: ``,
        size: 102400,
      },
    ],
    clientes: [
      {
        idCliente: `CLI-${unique}`,
        tipoVinculo: 'titular',
        nombreCompleto: 'Juan Perez Garcia',
        numeroDocumento: ownerDocumentId,
        email: `juan.${unique}@email.com`,
        telefono: '+51999999999',
      },
    ],
  };
}

export function buildUpdateDocumentsPayload(keyword) {
  const unique = buildUniqueSuffix();

  return {
    idFirma: String(keyword),
    documents: [
      {
        name: `contrato_firmado_${unique}.pdf`,
        s3KeyFirmado: `signed/contrato_firmado_${unique}.pdf`,
        urlExpiresAt: futureIsoDate(30),
      },
    ],
  };
}

export function buildCompletionPayload(keyword) {
  const unique = buildUniqueSuffix();

  return {
    idFirma: String(keyword),
    documents: [
      {
        name: `contrato_completado_${unique}.pdf`,
        providerKeyFirmado: `provider/signed/contrato_${unique}.pdf`,
        urlExpiresAt: futureIsoDate(30),
      },
    ],
  };
}
